WITH links AS (SELECT l.tenant_id,l.fbs_order_id,l.shipment_movement_id AS movement_id FROM fbs_shipment_reversal_ledger l WHERE l.shipment_movement_id IS NOT NULL UNION SELECT l.tenant_id,l.fbs_order_id,(x.value->>'movement_id')::uuid AS movement_id FROM fbs_shipment_reversal_ledger l CROSS JOIN LATERAL json_array_elements(l.ozon_positions_json::json) x(value) WHERE x.value->>'movement_id' IS NOT NULL AND x.value->>'movement_id' <> '') SELECT clock_timestamp() AS db_at,o.supply_id,s.name,s.status,count(DISTINCT m.id) AS movements,sum(m.quantity_delta) AS delta,count(DISTINCT o.id) AS orders,min(m.created_at) AS first_at,max(m.created_at) AS last_at FROM inventory_movements m JOIN links l ON l.movement_id=m.id AND l.tenant_id=m.tenant_id JOIN fbs_orders o ON o.id=l.fbs_order_id AND o.tenant_id=m.tenant_id LEFT JOIN fbs_supplies s ON s.id=o.supply_id WHERE m.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND m.product_id IN (SELECT DISTINCT p.product_id FROM fbs_order_products p JOIN fbs_orders o ON o.id=p.order_id WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.marketplace='ozon') AND m.movement_type='fbs_shipment' GROUP BY o.supply_id,s.name,s.status ORDER BY o.supply_id LIMIT 60
